import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Mesh, PlaneGeometry, Group } = ctx.THREE;

  const group = new Group();
  group.position.set(0, 3, 0);
  group.rotation.order = 'YXZ';
  group.scale.set(1, 1, 1);

  // Create backdrop gradient plane (engineered surface)
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: mix(
      color(0x0b0b10), // surface (dark base)
      color(0x16161d), // ink (upper tone)
      uv().y
    ),
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.renderOrder = 0;
  group.add(backdrop);

  // Load and apply image texture to plane
  const planeGeom = new PlaneGeometry(2.56, 1.6); // Aspect from atlas: 512/320
  const planeMat = new MeshBasicNodeMaterial({
    side: ctx.THREE.DoubleSide,
  });

  const plane = new Mesh(planeGeom, planeMat);
  plane.position.z = 0;
  plane.renderOrder = 1;
  group.add(plane);

  // Load texture asynchronously
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    planeMat.map = texture;
    planeMat.needsUpdate = true;
  });

  // Create text: "Collection" headline (96px, 400 weight)
  const textObj = ctx.fontAtlas.createText('Collection', {
    fontSize: 96,
    color: '#e8ecf2', // paper color for contrast on dark stage
    align: 'center',
  });
  textObj.position.set(0, -1.2, 0.1);
  textObj.scale.set(1, 1, 1);
  group.add(textObj);

  // Cleanup handler
  group.userData.cleanup = () => {
    backdropGeom.dispose();
    backdropMat.dispose();
    planeGeom.dispose();
    planeMat.dispose();
    if (planeMat.map) planeMat.map.dispose();
  };

  return group;
}
